  // One quote per overdue server, built from the SAME `renewalCharge` + `walletSplit`
  // pair that `settleOutstanding` and the sweep use. The three must never disagree:
  // a page that quotes a different total than the charge that follows is the exact
  // failure both of those call sites carry a comment about.
  const overdue = overdueServers.map((s) => {
    const charge = renewalCharge(s, prices);
    const split = walletSplit({
      dueCents: charge.totalCents,
      balanceCents: user.balanceCents,
      useWallet: true,
    });
    return {
      server: s,
      charge,
      split,
      view: dunningView(s, { hasCard: cardOnFile, graceDays, autoSuspend, now }),
    };
  });
  const totalOutstandingCents = overdue.reduce((sum, o) => sum + o.charge.totalCents, 0);
  // A server can be past its expiry date and still fully funded — the sweep runs every
  // ten minutes, so "overdue" and "short of money" are different things. Only the
  // second one is an emergency, and only it gets the red treatment.
  const anyShortfall = overdue.some((o) => o.split.cardCents > 0);
  // "The card failed" is not a column — `dunningStage` counts card attempts that
  // have FAILED for the current unpaid period, so a stage above zero while a card is
  // on file IS the saved card having been declined. Anything less specific here
  // would be guessing.
  const cardDeclined = cardOnFile && overdue.some((o) => o.view.inDunning);
  const fmtDay = (d: Date) =>
    d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  // Widened from its literal type on purpose: the copy below pluralises off this
  // number, and TypeScript rejects `=== 1` as impossible against the literal `3` —
  // which would leave the sentence unable to survive a change to the ladder.
  const retryAttempts: number = DUNNING_RETRY_ATTEMPTS;
  // "1, 3 and 5" — built from the real ladder rather than written out, so a change to
  // DUNNING_RETRY_ATTEMPTS reads correctly here instead of silently going stale.
  const retryDayList =
    RETRY_DAYS.length === 1
      ? String(RETRY_DAYS[0])
      : `${RETRY_DAYS.slice(0, -1).join(", ")} and ${RETRY_DAYS[RETRY_DAYS.length - 1]}`;

  // Bandwidth usage: metered transfer (bwIn + bwOut, written by the worker's
  // metering sweep) vs plan allowance (bandwidthTB * 1e12 bytes).
  //
  // This panel used to divide the raw columns by the allowance and print the
  // result. Nothing wrote those columns, so it read a permanent "0 B / 20 TB ·
  // 0%" under the title "Transfer used this cycle" — a figure that looked
  // authoritative and was pure fiction. Everything shown now goes through
  // bwUsageView, which reports the period the meter ACTUALLY covers and
  // withholds the percentage entirely until a sample exists.
