export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
  // This lookup was ALREADY lowercasing while register/login stored the address
  // verbatim, which is precisely why a `Alice@Example.com` signup could never be
  // reset. Both sides now share one definition rather than two that agreed by
  // luck — see lib/email-normalize.ts.
  const email = normalizeEmail(formData.get("email"));
  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
  // and enumeration probing. On limit, still report success below (no leak).
  const hdrs = await headers();
  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
  if (!rl.ok) return { sent: true };
  // Always report success (don't leak which emails exist)
  const user = await db.user.findUnique({ where: { email } });
  if (user) {
    const { randomBytes, createHash } = await import("node:crypto");
    const token = randomBytes(32).toString("base64url");
    const tokenHash = createHash("sha256").update(token).digest("hex");
    await db.passwordResetToken.create({
      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
    });
    const { sendMail, emails } = await import("./mailer");
    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
    const tpl = emails.passwordReset(link);
    // Consult the notification policy, which classifies `password_reset` as
    // CRITICAL and therefore returns true without even loading the preferences.
    // The call is here so the POLICY decides, not this call site: a reset link is
    // the only route back into a locked-out account, so honouring an "Account
    // email: off" checkbox here would lock the customer out of their own account
    // permanently — the mirror image of swallowing a suspension warning.
    if (await mayDeliverTo(user.id, "password_reset", "email")) {
      await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
    }
    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
  }
  return { sent: true };
}

export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < 8) return { error: "Password must be at least 8 characters." };
  const { createHash } = await import("node:crypto");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
  if (!row || row.usedAt || row.expiresAt < new Date()) {
    return { error: "This reset link is invalid or has expired. Request a new one." };
  }
  await db.$transaction([
    // Bump sessionVersion so any sessions predating the reset are evicted.
    db.user.update({
      where: { id: row.userId },
      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
    }),
    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
  ]);
  return { ok: true };
}

