// Type-only import (erased at build) so this module can be pulled into a client
// component without dragging `lib/monitoring`'s Prisma/Proxmox imports along.
import type { CompStatus } from "./monitoring";

/**
 * The single source of truth for how a platform health roll-up is WORDED.
 *
 * There used to be two: `app/status/page.tsx` computed a real status and named
 * it, and `components/marketing/MarketingFooter.tsx` printed "All systems
 * operational" from a string literal next to a pulsing green dot, on all 22
 * marketing pages, having consulted nothing. During an outage — the one moment
 * a customer reads a status line — the footer insisted everything was fine.
 *
 * Both render sites now take their words AND their colour from this table, so a
 * status the footer shows is a status something actually measured.
 */
export const OVERALL_TITLE: Record<CompStatus, string> = {
  operational: "All systems operational",
  degraded: "Some systems are degraded",
  down: "We're experiencing an outage",
};

/** Dot colour per status — the same tokens the /status page components use. */
export const STATUS_DOT: Record<CompStatus, string> = {
  operational: "bg-emerald-400",
  degraded: "bg-amber-400",
  down: "bg-red-400",
};

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import type { CompStatus } from "@/lib/monitoring";
import { OVERALL_TITLE, STATUS_DOT } from "@/lib/status-copy";

/**
 * The footer's platform-status line.
 *
 * This used to be the literal string "All systems operational" beside a pulsing
 * green dot, hardcoded into the footer of every marketing page. It consulted
 * nothing. During a real outage the whole site went on insisting everything was
 * fine — the same class of defect as a job reporting success it never verified.
 *
 * Why a client component rather than `await getHealth()` in the footer: every
 * marketing page is prerendered to static HTML at build time (see
 * `.next/server/app/*.html`), so a server-side read would freeze whatever the
 * platform looked like during `next build` into the footer forever — a fresher
 * lie, not a fix. Fetching `/api/health` after mount is the only way this line
 * can be true on a page that is otherwise static.
 *
 * Until the probe answers — and if it fails, or the browser is offline — we
 * render the link with a neutral dot and the word "Status" and make NO claim.
 * Saying nothing is the correct output when nothing is known.
 */

type Health = {
  web?: { status: CompStatus };
  db?: { status: CompStatus };
  worker?: { status: CompStatus };
  proxmox?: { status: CompStatus };
};

/** Worst-of roll-up, mirroring `overallStatus()` in lib/monitoring. */
function rollUp(h: Health): CompStatus | null {
  const all = [h.web?.status, h.db?.status, h.worker?.status, h.proxmox?.status];
  if (all.some((s) => s === undefined)) return null;
  if (all.includes("down")) return "down";
  if (all.includes("degraded")) return "degraded";
  return "operational";
}

export function FooterStatus() {
  const [status, setStatus] = useState<CompStatus | null>(null);

  useEffect(() => {
    let alive = true;
    // /api/health answers a coarse, secret-free status and caches ~15s in
    // process, so one fetch per page view costs the platform almost nothing.
    // A 503 body is still a valid report ("db down"), so parse it either way.
    fetch("/api/health", { cache: "no-store" })
      .then((r) => r.json())
      .then((d) => {
        if (alive && d && typeof d === "object") setStatus(rollUp(d as Health));
      })
      .catch(() => {
        /* unreachable — keep the neutral "Status" line rather than guessing */
      });
    return () => {
      alive = false;
    };
  }, []);

  return (
    <Link
      href="/status"
      className="flex items-center gap-2 text-xs transition-colors hover:text-slate-300"
    >
      <span
        className={`h-2 w-2 rounded-full ${
          status ? `${STATUS_DOT[status]} animate-pulse-dot` : "bg-slate-600"
        }`}
      />
      {status ? OVERALL_TITLE[status] : "Status"}
    </Link>
  );
}

