 */
useEffect(() => {
  document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
}, [collapsed]);

/**
 * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
 * off-canvas panel translated out of view; at `lg` and up it is the ordinary
 * page sidebar and must never be hidden or inerted.
 *
 * Starts `true` (desktop) so the server render and the first client render
 * agree, and so a JS-less or pre-hydration page never has its navigation
 * inerted. The listener corrects it a tick later.
 */
const [isDesktopRail, setIsDesktopRail] = useState(true);
useEffect(() => {
  const mq = window.matchMedia("(min-width: 1024px)");
  const sync = () => setIsDesktopRail(mq.matches);
