"use client";

import { useActionState, useState, useTransition } from "react";
import { createTicket, replyTicket, setTicketStatus } from "@/lib/actions-support";

/**
 * Support ticket forms.
 *
 * Everything the customer types here is CONTROLLED on purpose. React 19 resets
 * uncontrolled inputs on every `<form action={fn}>` submit, so a rejected ticket
 * used to blank the subject, the priority and a body of up to 10,000 characters
 * — written, by definition, by someone already having a bad day, and with no way
 * to get it back. The same reasoning applies to the reply box.
 */

/** Matches the server's `createTicket` minimums so the message can be specific. */
const SUBJECT_MIN = 3;
const BODY_MIN = 5;

export function NewTicketForm() {
  const [open, setOpen] = useState(false);
  const [state, action, pending] = useActionState(createTicket, {});
  const [subject, setSubject] = useState("");
  const [priority, setPriority] = useState("NORMAL");
  const [body, setBody] = useState("");
  // Client-side validation message. The server's own rules still run; this exists
  // because submitting an empty ticket used to do NOTHING — no message, no
  // movement, no clue which field was at fault.
  const [invalid, setInvalid] = useState<string | null>(null);

  const subjectShort = subject.trim().length < SUBJECT_MIN;
  const bodyShort = body.trim().length < BODY_MIN;

  return (
    <div>
      <div className="flex justify-end">
        {/*
          `type="button"`: with no type a <button> is a submit control, which is
          the wrong default for a control whose entire job is to close a form.
        */}
        <button
          type="button"
          className={open ? "btn-secondary" : "btn-primary"}
          onClick={() => setOpen((o) => !o)}
        >
          {open ? "Cancel" : "+ New ticket"}
        </button>
      </div>
      {open && (
        <form
          action={action}
          onSubmit={(e) => {
            if (subjectShort || bodyShort) {
              e.preventDefault();
              setInvalid(
                subjectShort && bodyShort
                  ? `Add a subject (at least ${SUBJECT_MIN} characters) and a message (at least ${BODY_MIN} characters) so we know what to look at.`
                  : subjectShort
                    ? `Add a subject of at least ${SUBJECT_MIN} characters — it's what we see first in the queue.`
                    : `Add a message of at least ${BODY_MIN} characters. Include the server hostname and any error text.`
              );
              return;
            }
            setInvalid(null);
          }}
          className="card mt-4 animate-fade-up space-y-4"
        >
          {(state?.error || invalid) && (
            <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
              {state?.error || invalid}
            </div>
          )}
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-[1fr_180px]">
            <div>
              <label className="label" htmlFor="ticket-subject">Subject</label>
              <input
                id="ticket-subject"
                className="input"
                name="subject"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                required
                minLength={SUBJECT_MIN}
                maxLength={150}
                placeholder="Briefly, what's going on?"
              />
            </div>
            <div>
              <label className="label" htmlFor="ticket-priority">Priority</label>
              <select
                id="ticket-priority"
                className="input"
                name="priority"
                value={priority}
                onChange={(e) => setPriority(e.target.value)}
              >
                <option value="LOW">Low</option>
                <option value="NORMAL">Normal</option>
                <option value="HIGH">High</option>
                <option value="URGENT">Urgent</option>
              </select>
            </div>
          </div>
          <div>
            <label className="label" htmlFor="ticket-body">Message</label>
            <textarea
              id="ticket-body"
              className="input min-h-32 resize-y"
              name="body"
              value={body}
              onChange={(e) => setBody(e.target.value)}
              required
              minLength={BODY_MIN}
              maxLength={10000}
              placeholder="Include the server hostname and any error messages — the more detail, the faster we can help."
            />
          </div>
          <div className="flex justify-end">
            <button type="submit" className="btn-primary px-6" disabled={pending}>
              {pending ? "Opening…" : "Open ticket"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

export function ReplyForm({ ticketId }: { ticketId: string }) {
  const [state, action, pending] = useActionState(replyTicket, {});
  // Controlled for the same reason as the ticket body above: a rejected reply
  // must not throw away what the customer wrote.
  const [body, setBody] = useState("");
  const [invalid, setInvalid] = useState<string | null>(null);
  return (
    <form
      action={action}
      onSubmit={(e) => {
        if (body.trim().length < 2) {
          e.preventDefault();
          setInvalid("Write a reply first — even a couple of words is enough to reopen the thread.");
          return;
        }
        setInvalid(null);
      }}
      className="space-y-3"
    >
      <input type="hidden" name="ticketId" value={ticketId} />
      {(state?.error || invalid) && (
        <p className="text-sm text-red-400">{state?.error || invalid}</p>
      )}
      <textarea
        className="input min-h-28 resize-y"
        name="body"
        value={body}
        onChange={(e) => setBody(e.target.value)}
        required
        minLength={2}
        maxLength={10000}
        aria-label="Reply"
        placeholder="Write a reply…"
      />
      <div className="flex justify-end">
        <button type="submit" className="btn-primary px-6" disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
      </div>
    </form>
  );
}

export function TicketStatusButton({ ticketId, status }: { ticketId: string; status: string }) {
  const [pending, start] = useTransition();
  const closed = status === "CLOSED";
  return (
    <button
      type="button"
      className={closed ? "btn-secondary" : "btn-danger"}
      disabled={pending}
      onClick={() => start(() => setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED"))}
    >
      {pending ? "…" : closed ? "Reopen ticket" : "Close ticket"}
    </button>
  );
}

